css:
.df-media {
  margin: 14px 0;
  color: var(--c-text)
}

.df-media-img {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  object-fit: var(--df-fit,contain);
  background: var(--c-surface);
  border: 1px solid var(--c-border)
}

.df-media-img.is-clickable,.content img.is-clickable {
  cursor: zoom-in
}

.df-media-caption {
  margin-top: 7px;
  color: var(--c-muted);
  font-size: 13px;
  line-height: 1.5
}

.df-media-missing {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 160px;
  border: 1.5px dashed var(--c-border);
  border-radius: 8px;
  background: rgba(22,27,34,.35);
  color: var(--c-muted);
  font-family: var(--mono);
  font-size: 12px
}

.df-gallery {
  display: grid;
  gap: 10px
}

.df-gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit,minmax(var(--df-min,220px),1fr));
  gap: 10px
}

.df-gallery-scroll {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: 8px
}

.df-gallery-scroll .df-gallery-item {
  flex: 0 0 min(78vw,var(--df-item,420px));
  scroll-snap-align: start
}

.df-gallery-item img {
  width: 100%;
  aspect-ratio: var(--df-ratio,16/10);
  object-fit: var(--df-fit,cover)
}

.df-video {
  width: 100%;
  max-width: 100%;
  border-radius: 8px;
  background: #000;
  border: 1px solid var(--c-border);
  display: block
}

.df-media-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9200;
  background: rgba(0,0,0,.88);
  display: none;
  align-items: center;
  justify-content: center;
  padding: 28px;
  cursor: zoom-out
}

.df-media-lightbox.open {
  display: flex
}

.df-media-lightbox img,.df-media-lightbox video {
  max-width: 94vw;
  max-height: 90vh;
  object-fit: contain;
  border-radius: 8px;
  box-shadow: 0 18px 60px rgba(0,0,0,.55)
}

.df-media-close {
  position: absolute;
  right: 18px;
  top: 16px;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 999px;
  background: rgba(255,255,255,.12);
  color: #fff;
  font-size: 20px;
  cursor: pointer
}

@media(max-width:720px) {
  .df-gallery-grid {
    grid-template-columns: 1fr
  }

  .df-gallery-scroll .df-gallery-item {
    flex-basis: 86vw
  }}

