(function(){
  function esc(s){return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
  function mediaUrl(key){return (window.DocForge&&DocForge.media(key))||key||'';}
  function ensureBox(){var box=document.querySelector('.df-media-lightbox');if(box)return box;box=document.createElement('div');box.className='df-media-lightbox';box.innerHTML='<button class="df-media-close" type="button" aria-label="Close">×</button><div class="df-media-stage"></div>';document.body.appendChild(box);box.addEventListener('click',function(e){if(e.target===box||e.target.classList.contains('df-media-close'))closeBox();});document.addEventListener('keydown',function(e){if(e.key==='Escape')closeBox();});return box;}
  function closeBox(){var box=document.querySelector('.df-media-lightbox');if(!box)return;box.classList.remove('open');box.querySelector('.df-media-stage').innerHTML='';}
  function setupGalleries(){document.querySelectorAll('[data-df-gallery-keys]').forEach(function(box){if(box.dataset.dfReady)return;box.dataset.dfReady='1';var mode=box.dataset.dfGalleryMode||'grid';box.className=mode==='scroll'?'df-gallery-scroll':'df-gallery-grid';var light=box.dataset.dfLightbox!== 'false';var keys=(box.dataset.dfGalleryKeys||'').split(/[,s]+/).map(function(k){return k.trim();}).filter(Boolean);box.innerHTML=keys.map(function(key){var src=mediaUrl(key);return '<div class="df-gallery-item"><img class="df-media-img'+(light?' is-clickable':'')+'" src="'+esc(src)+'" alt="" loading="lazy" data-df-lightbox="'+(light?'image':'')+'"></div>';}).join('');});}
  function setupLightbox(){document.querySelectorAll('.content img:not([data-df-no-lightbox]),[data-df-lightbox="image"]').forEach(function(img){if(img.dataset.dfLightboxReady)return;img.dataset.dfLightboxReady='1';img.classList.add('is-clickable');img.addEventListener('click',function(){var box=ensureBox();box.querySelector('.df-media-stage').innerHTML='<img src="'+esc(img.currentSrc||img.src)+'" alt="'+esc(img.alt||'')+'">';box.classList.add('open');});});}
  DocForge.register({id:'media-viewer',tagSchema:{'media-image':{description:'Render one image by media key or URL.',attrs:['key','src','alt','caption','fit','lightbox']},'media-video':{description:'Render one video by media key or URL.',attrs:['key','src','poster','caption','controls','autoplay','loop']},'media-gallery':{description:'Render multiple images by media keys or URLs.',attrs:['keys','mode','fit','ratio','min','caption','lightbox']}},onLoad:function(){setupGalleries();setupLightbox();}});
})();
